import React from "react";
import { useParams, Link } from "react-router-dom";
import { useCart } from "./CartContext";

const OrderDetails = () => {
    const { id } = useParams();
    const { orders } = useCart();

    const order = orders.find((o) => o.id.toString() === id);

    if (!order) {
        return <p className="text-center mt-5 text-danger">Không tìm thấy đơn hàng.</p>;
    }

    return (
        <div className="container mt-5">
            <h2 className="mb-4 text-center text-primary">Chi tiết đơn hàng #{order.id}</h2>
            <div className="mb-3">
                <strong>Họ & Tên:</strong> {order.name} <br />
                <strong>Địa chỉ:</strong> {order.address} <br />
                <strong>Thông tin:</strong> {order.info}
            </div>
            <h4>Danh sách sản phẩm:</h4>
            {order.items.map((item, index) => (
                <div key={index} className="d-flex align-items-center mb-2 p-2 border rounded">
                    <img
                        src={item.image}
                        alt={item.name}
                        className="rounded-circle"
                        style={{ width: "60px", height: "60px", objectFit: "cover" }}
                    />
                    <div className="ms-3">
                        <p className="mb-0">{item.name}</p>
                        <p className="mb-0 text-muted">{item.price.toLocaleString()} VNĐ x {item.quantity}</p>
                    </div>
                </div>
            ))}
            <h4 className="mt-4">Tổng tiền: <span className="text-success">{order.items.reduce((sum, item) => sum + item.price * item.quantity, 0).toLocaleString()} VNĐ</span></h4>
            <Link to="/orders" className="btn btn-secondary mt-3">← Quay lại danh sách đơn</Link>
        </div>
    );
};

export default OrderDetails;
